-- Generated by model/lib/sql/generate.mjs. Loads IMPORT Unit Weight from cells/IMPORT Unit Weight.csv in the folder of input cells. Two rows for one cell add up.
-- @csv cells/IMPORT Unit Weight.csv
INSERT INTO "IMPORT Unit Weight" SELECT coalesce(k0."SKU", fpabench_error('cells name a member SKU does not have: ' || c."SKU")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim SKU" k0 ON k0.name = c."SKU"
GROUP BY 1
ON CONFLICT ("SKU") DO UPDATE SET v = EXCLUDED.v;
ANALYZE "IMPORT Unit Weight";
